"App ops need ADB, Shizuku or Root. Set up a working mode first.": "Для App Ops нужен ADB, Shizuku или Root. Сначала настройте режим работы.",
"App page on device": "Страница приложения на устройстве",
"App related library data.": "Данные библиотек, связанные с приложениями.",
"App shortcut icons": "Значки ярлыков приложений",
"App sources": "Источники приложений",
