"App update": "Обновление приложения",
"App update failed": "Не удалось обновить приложение",
"App updated": "Приложение обновлено",
"App-specific": "Для конкретного приложения",
"App: ADB Application Manager Pro ? (build ?)": "Приложение: ADB Application Manager Pro ? (сборка ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner может очищать кэши, до которых не добраться через доступ к файлам (кнопка «Очистить кэш» на экране «Хранилище» приложения), нажимая за вас в системных настройках. Для этого ему нужна служба специальных возможностей этого приложения. Служба действует только пока AppCleaner очищает кэши: открывает экран «О приложении» одного приложения за другим, нажимает «Очистить кэш» и останавливается, когда экран гаснет или блокируется. Накладка на экране показывает, что происходит, и позволяет отменить. Ничего не читается и никуда не отправляется. В Android 13 и новее для приложения, установленного из файла, сначала может понадобиться «Разрешить ограниченные настройки» («О приложении» этого приложения, меню с тремя точками).",
