"Apps patched from now on are signed with the new key. Android will not install them over an app that was signed with the old key; export the old one first if you may need it.": "Приложения, пропатченные с этого момента, подписываются новым ключом. Android не установит их поверх приложения, подписанного старым ключом; если старый может понадобиться, сначала экспортируйте его.",
