"Audio": "Аудио",
"Aurora Store": "Aurora Store",
"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store — клиент Play Store с открытым исходным кодом. Автоматическое определение версий в Play запланировано на будущее (для него нужна анонимная авторизация в Play); пока каждое приложение направляется на свою страницу в магазине, которая открывается в Aurora Store, если он установлен.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: установлен · Play Store: установлен. Нажмите приложение ниже, чтобы открыть его страницу в магазине.",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: установлен · Play Store: не установлен. Нажмите приложение ниже, чтобы открыть его страницу в магазине.",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: не установлен · Play Store: установлен. Нажмите приложение ниже, чтобы открыть его страницу в магазине.",
"Aurora Store: not installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: не установлен · Play Store: не установлен. Нажмите приложение ниже, чтобы открыть его страницу в магазине.",
