"Browser Use": "Browser Use",
"Browser Use did not start the task.": "Browser Use не запустил задачу.",
"Browser Use failed before it had an answer.": "Browser Use завершился ошибкой, не дав ответа.",
"Browser Use finished without an answer.": "Browser Use закончил без ответа.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use — агент-браузер с открытым кодом; это его облако, у которого для новых аккаунтов есть бесплатный уровень. Кнопка Ask agent запускает короткую задачу в браузере, которая ищет ответ на вопрос в вебе: это может занять минуту-две и тратит немного кредита. Он нужен только для кнопок Ask agent, это не чат. Проверка ключа ничего не стоит.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use работал слишком долго (больше 4 минут). Попробуйте позже.",
"Browser Use was stopped before it had an answer.": "Browser Use остановлен, не дав ответа.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Автоматизация браузера. Требует Node и загрузки Chromium, что может быть тяжело для телефона.",
