"Caches that file access cannot reach are cleared with the accessibility service: the screen shows the settings of one app after the other for a moment.": "Кэши, до которых не добраться через доступ к файлам, очищаются через службу специальных возможностей: на экране на мгновение появляются настройки одного приложения за другим.",
