"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI не нашёл ответа. Попробуйте веб-поиск или другого агента.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI — веб-краулер с открытым кодом; это его облако. Новый аккаунт получает бесплатные кредиты и бесплатный месячный лимит, без карты. Кнопка Ask agent отправляет вопрос в его службу ответов, которая ищет в вебе, читает страницы и пишет ответ. Он нужен только для кнопок Ask agent, это не чат. Проверка тратит один кредит.",
