"Edited": "Изменённые",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Изменение APK меняет его содержимое, поэтому подпись перестаёт совпадать. Android не установит его, пока он не будет подписан заново: используйте «Подписать» (приложение подписывает собственным ключом).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Изменение APK меняет его содержимое, поэтому подпись перестаёт совпадать. Android не установит его, пока он не будет подписан заново; «Подписать» делает это ключом этого приложения.",
"Effort": "Усилие",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "«Усилие» влияет только на агентов, у чьего API есть такая настройка (Claude, ChatGPT, Gemini, Grok); для остальных значение сохраняется, но не действует при общении по API-ключу, и ни один из них не передаёт его собственному инструменту входа в Termux.",
