"Errors": "Ошибки",
"Errors only": "Только ошибки",
"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Все приложения из каталога F-Droid или из любого известного стороннего репозитория. Выберите репозиторий, просматривайте приложения по категориям и устанавливайте их напрямую — загрузки сверяются с опубликованным в репозитории SHA-256.",
"Every app that is not enabled is saved.": "Сохраняются все приложения, которые не включены.",
"Every change goes into the history, so it can be reverted.": "Каждое изменение попадает в историю, поэтому его можно отменить.",
"Every level is hidden - tap the color key above to show some.": "Все уровни скрыты — нажмите на цветовую легенду выше, чтобы показать некоторые.",
"Every palette has a light and a dark version": "У каждой палитры есть светлая и тёмная версии",
"Every setting here goes back to what SD Maid SE ships with.": "Каждая настройка здесь вернётся к значению по умолчанию SD Maid SE.",
"Every source is off. Turn some on in Settings.": "Все источники выключены. Включите некоторые в настройках.",
"Every uninstall, disable and restore, with one-tap undo": "Все удаления, отключения и восстановления — с отменой в одно касание",
"Everything is up to date": "Всё актуально",
"Everything is up to date.": "Всё обновлено.",
"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa не нашёл ответа на этот вопрос. Попробуйте поиск в интернете или другого агента.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa — поисковая система, созданная для ИИ. Её сервис ответов ищет в интернете и пишет короткий ответ с указанием источников. Новому аккаунту дают бесплатные кредиты. Проверка ключа делает один небольшой поиск (доли цента). Кнопка «Спросить агента» отправляет ему вопрос; пока вы не нажмёте её, ничего не отправляется.",
