"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Найдено чтением имён классов в коде приложения на этом телефоне; ничего никуда не отправляется. Список трекеров: Exodus Privacy, лицензия ODbL 1.0. Код, переименованный сжимателем (R8, ProGuard) или загруженный позже, может скрыть трекер, поэтому малое число не доказывает, что их нет.",
