"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Заморозка, debloat, установка, резервные копии и просмотр сведений о любом приложении на телефоне — прямо с телефона: через ADB, отладку по Wi-Fi, Shizuku или Root. Без компьютера, без аккаунта, без рекламы.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Из файлового менеджера: установка через привилегированный режим, при этом проверки подписи в этом приложении отключены. Android всё равно сам проверяет подписи: APK, подпись которого он не может проверить, подписывается ключом этого приложения и устанавливается, а приложение, подписанное кем-то другим, можно заменить только после его удаления (сначала вас спросят).",
