"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse и Deepseek подключаются по API-ключу с сайта поставщика (ссылки ниже). Использование оплачивается у поставщика с аккаунта, к которому относится ключ; у Gemini API от Google есть также бесплатный уровень, где Google может использовать отправляемые вами данные для улучшения своих продуктов.",
