"Hands the queued files to Android's Bluetooth sharing, which asks which paired device gets them. Most watches, Wear OS included, cannot receive files this way: for a Wear OS watch use the Bluetooth link under Add device and send over ADB instead.": "Передаёт файлы из очереди системной функции Android «Передача по Bluetooth», которая спросит, на какое сопряжённое устройство их отправить. Большинство часов, включая Wear OS, не могут принимать файлы таким способом: для часов Wear OS используйте связь по Bluetooth в разделе «Добавить устройство» и отправляйте через ADB.",
