"IzzyOnDroid serves the developer's own release builds of open-source apps. The file is downloaded here.": "IzzyOnDroid предлагает релизные сборки приложений с открытым кодом от самих разработчиков. Файл скачивается здесь.",
"JVM code cache. Blocks of bytecode compiled into native code.": "Кэш кода JVM. Блоки байт-кода, скомпилированные в нативный код.",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan бесплатно запускает ИИ-модели на вашем компьютере. На компьютере: Jan → Настройки → Local API Server: укажите хост 0.0.0.0 и запустите сервер, затем введите здесь адрес компьютера (например, http://192.168.1.20:1337/v1). Версии Jan для Android нет.",
