"Ollama (on-device)": "Ollama (на устройстве)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama пока не запущен на этом телефоне. Установите его ниже или введите адрес компьютера, на котором он работает.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama запускает модель для программирования прямо на этом телефоне: бесплатно и офлайн после загрузки модели. Устанавливается в Termux; маленькие модели (от 1,5B до 3B) лучше всего работают на телефоне. Ollama на компьютере тоже подходит: пусть он слушает все адреса, а здесь введите адрес компьютера (например, 192.168.1.20:11434/v1).",
"On": "Вкл.",
"On device": "На устройстве",
"On this phone": "На этом телефоне",
"On:": "Включено:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "В каждой оболочке — одна команда за раз; длинный вывод обрезается и на экране, и в том, что отправляется агенту.",
"One file only": "Только один файл",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Один ключ на всё приложение. Проверка в «Установщике» и проверка в Morphe Helper используют его; ни одна не запрашивает его снова, а только указывают сюда, когда его нет.",
"One more place to find apps": "Ещё одно место для поиска приложений",
"One package per line. Duplicate entries are removed automatically.": "Один пакет в строке. Повторяющиеся записи удаляются автоматически.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Один исходный цвет, девять способов превратить его в целую тему: акцент, фон, карточки и текст — в светлом и тёмном режимах. Выбор стиля строит тему из исходного цвета ниже.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Использует только AppCleaner: он открывает системный экран «О приложении» каждого приложения и нажимает «Очистить кэш» — для кэшей, до которых не добраться через доступ к файлам. Больше ничего не делает, никогда не читает содержимое экрана, кроме этих экранов, и останавливается, когда экран гаснет.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "В эти файлы записывается только помеченный блок; то, что в них уже есть, остаётся, а повторный запуск обновляет блок, а не добавляет новый.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Добавляйте только источники, которым доверяете. Источник патчей определяет, что окажется внутри ваших пропатченных приложений.",
"Only apps installed on this phone": "Только приложения, установленные на этом телефоне",
"Only base": "Только базовый",
"Only hidden files are here. Tick Show hidden files to see them.": "Здесь только скрытые файлы. Включите «Показывать скрытые файлы», чтобы увидеть их.",
"Only include common media files, documents and archives.": "Включать только распространённые медиафайлы, документы и архивы.",
"Only list what would run for each app. Nothing is run.": "Только показать, что выполнится для каждого приложения. Ничего не запускается.",
"Only patches for apps installed on this phone": "Только патчи для приложений, установленных на этом телефоне",
"Only split bundles are listed for this app. Turn on Allow split APK.": "Для этого приложения есть только составные пакеты. Включите «Разрешить split APK».",
"Only text and compiled XML files can be compared line by line": "Построчно можно сравнивать только текстовые файлы и скомпилированный XML",
"Only the app name you typed is sent.": "Отправляется только введённое название приложения.",
"Only the lines written by the app you pick": "Только строки, записанные выбранным приложением",
"Only the selected apps are saved.": "Сохраняются только выбранные приложения.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Меняется только текст этого приложения; имена, пути и команды в блоках кода сохраняют свой шрифт.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "Ему отправляется только этот пример вопроса: можно ли отключить пакет «Калькулятор».",
