"OpenCode": "OpenCode",
"OpenCode is an open-source coding agent. After installing it, sign in to a provider with opencode auth login: it supports a ChatGPT plan, GitHub Copilot and API keys of many providers.": "OpenCode — агент для кода с открытым исходным кодом. После установки войдите в аккаунт провайдера командой opencode auth login: поддерживаются подписка ChatGPT, GitHub Copilot и API-ключи многих провайдеров.",
