"Pair Device": "Сопрячь устройство",
"Pair and connect a Wear OS watch or any Android device over Wi-Fi or Bluetooth. Then you can manage its apps, send apps to it, read its log, browse its files and change its settings from here.": "Сопрягите и подключите часы Wear OS или любое устройство Android по Wi-Fi или Bluetooth. После этого вы сможете отсюда управлять его приложениями, отправлять ему приложения, читать его журнал, просматривать его файлы и менять его настройки.",
"Pair and connect over Wi-Fi, or link a watch over Bluetooth": "Сопрягите и подключите по Wi-Fi или свяжите часы по Bluetooth",
"Pair device using Android native Wireless Debugging dialog in Developer Options.": "Сопрягите устройство через системный диалог отладки по Wi-Fi в параметрах разработчика.",
"Paired. Now connect.": "Сопряжено. Теперь подключитесь.",
