"Partitioned uninstalled system apps": "Удалённые системные приложения",
"Passes each tool's own option for that (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI). Off: they only do what needs no approval.": "Передаёт каждому инструменту его собственный параметр для этого (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI). Выкл.: они делают только то, что не требует подтверждения.",
