"Patch anyway": "Всё равно пропатчить",
"Patch apps with Morphe, on this phone: pick the patches, build the APK, sign it and install it.": "Патчите приложения с помощью Morphe прямо на этом телефоне: выберите патчи, соберите APK, подпишите и установите.",
"Patch sources": "Источники патчей",
"Patch this file": "Пропатчить этот файл",
