"Patched / modified": "Пропатчено / изменено",
"Patched APKs": "Пропатченные APK",
"Patched apps are signed with a key that is made on this phone the first time. Keep using the same key to update a patched app in place.": "Пропатченные приложения подписываются ключом, который создаётся на этом телефоне в первый раз. Продолжайте использовать тот же ключ, чтобы обновлять пропатченное приложение поверх прежнего.",
"Patcher": "Патчер",
"Patcher settings": "Настройки патчера",
"Patches": "Патчи",
"Patches from different sources are built independently and can conflict. Sticking to one source per app is the safe default. Continue?": "Патчи из разных источников собираются независимо и могут конфликтовать. Безопасно по умолчанию использовать один источник на приложение. Продолжить?",
