"Permission": "Разрешение",
"Permission Manager": "Менеджер разрешений",
"Permissions": "Разрешения",
"Permissions 0 of 0 granted, 0 app op restored": "Разрешения: выдано 0 из 0, восстановлено App Ops: 0",
"Permissions 0 of 0 granted, 0 app ops restored": "Разрешения: выдано 0 из 0, восстановлено App Ops: 0",
"Perplexity": "Perplexity",
"Phone makers and apps add settings of their own.": "Производители телефонов и приложения добавляют свои собственные настройки.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Выберите набор патчей .mpp из хранилища. Локальный источник никогда не обновляется сам: выберите новый файл, когда он выйдет.",
"Pick a Coding Agent in the Terminal first": "Сначала выберите агента для кода в Терминале",
"Pick a package file to read it and choose how to install it.": "Выберите файл пакета, чтобы прочитать его и выбрать способ установки.",
"Pick a package first": "Сначала выберите пакет",
"Pick an agent under Coding Agents to chat": "Чтобы начать чат, выберите агента в списке «Агенты для кода»",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Выберите агента, затем модель и усилие (Низкое, Среднее или Высокое: насколько усердно агент должен думать). В первый раз для обоих выбран средний вариант, а агент запрашивает то, что ему нужно (API-ключ, адрес сервера или вход в аккаунт), и проверяет это до начала работы.",
"Pick at least one agent": "Выберите хотя бы одного агента",
"Pick at least one patch": "Выберите хотя бы один патч",
"Pick one to fill the fields below, or write your own": "Выберите пресет, чтобы заполнить поля ниже, или введите свой",
"Pick which split APKs to install. The base APK is always included, and every other split starts ticked because \"Select all splits by default\" is on.": "Выберите, какие split-APK устанавливать. Базовый APK включается всегда, а все остальные split отмечены, потому что включена опция «Выбирать все split по умолчанию».",
"Pick which split APKs to install. The base APK is always included; the splits that fit this phone are ticked and the others are left off for you to add.": "Выберите, какие split-APK устанавливать. Базовый APK включается всегда; split-части, подходящие этому телефону, отмечены, остальные не отмечены — их можно добавить вручную.",
