"Termux is not set up for this app yet.": "Termux ещё не настроен для этого приложения.",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux готов: vim, nano, git и python установлены, а у bash есть стартовый .bashrc. Откройте настоящий терминал для программ на весь экран.",
