"That name is already used here": "Это имя здесь уже занято",
"That name is not allowed": "Это имя недопустимо",
"That one would stop the adb this app runs on, so it is not sent.": "Эта команда остановила бы adb, на котором работает приложение, поэтому она не отправлена.",
"That part of the guide is not there.": "Этого раздела в руководстве нет.",
"That password did not work. Try again.": "Этот пароль не подходит. Попробуйте снова.",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "Такой шаблон может привести к зависанию списка (повтор внутри повтора или слишком длинный), поэтому поиск идёт как по обычному тексту.",
"That port is used by this phone's own ADB. Use another, like 4444.": "Этот порт занят собственным ADB этого телефона. Используйте другой, например 4444.",
"That recording could not be read": "Не удалось прочитать эту запись",
