"The # button switches to commands.": "Кнопка # переключает на команды.",
"The $ button switches to commands.": "Кнопка $ переключает на команды.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "Ключ ADB и ключ подписи APK создаются на этом телефоне и никогда его не покидают.",
"The APK": "APK",
"The APK is ready (saved from the browser).": "APK готов (сохранён из браузера).",
"The APK is ready.": "APK готов.",
"The Action Button": "Кнопка действия",
"The Bluetooth link could not be set up.": "Не удалось установить связь по Bluetooth.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "Кнопка MCP открывает панель, где можно дать агенту дополнительные инструменты (файлы, интернет, браузер, GitHub...) через Model Context Protocol. Выберите пресет или задайте свой: имя, локальную команду или удалённый адрес и нужные ключи или заголовки. Выберите агентов, которым его добавить, — один и тот же сервер можно добавить сразу двум или нескольким, так как каждый агент хранит его в своём файле.",
"The Morphe engine is not in this build of the app": "Движка Morphe нет в этой сборке приложения",
"The PDF could not be shown.": "Не удалось показать PDF.",
"The Play Store gives no download to other apps. This opens the app's page in the Play Store.": "Play Store не отдаёт файлы другим приложениям. Откроется страница приложения в Play Store.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Оболочка Rish завершилась. Нажмите «Режим Rish», чтобы открыть новую.",
"The Rish shell is no longer running.": "Оболочка Rish больше не работает.",
"The Terminal needs the app (it is not available in a plain browser)": "Терминал работает только в приложении (в обычном браузере он недоступен)",
"The UAD-NG list has not been downloaded yet.": "Список UAD-NG ещё не скачан.",
"The UAD-NG list has nothing on this app": "В списке UAD-NG нет сведений об этом приложении",
"The VirusTotal scan did not work": "Проверка VirusTotal не удалась",
"The VirusTotal scan did not work.": "Проверка VirusTotal не удалась.",
"The accessibility service is not ready": "Служба специальных возможностей не готова",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Служба специальных возможностей не готова (не подключена), поэтому кэши, которые может очистить только она, остаются. После этого используйте «Очистить остальное через специальные возможности» на карточке AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Служба специальных возможностей не готова (выключена), поэтому кэши, которые может очистить только она, остаются. После этого используйте «Очистить остальное через специальные возможности» на карточке AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Служба специальных возможностей не готова (согласие не дано), поэтому кэши, которые может очистить только она, остаются. После этого используйте «Очистить остальное через специальные возможности» на карточке AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "Средства на аккаунте закончились, или достигнут лимит расходов.",
"The agent is still working: STOP it first": "Агент ещё работает: сначала нажмите STOP",
"The agent pauses after this many steps.": "После указанного числа шагов агент делает паузу.",
"The app": "Приложение",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "Приложение бесплатное и останется таким. Если оно сэкономило вам время, чашка кофе поможет мне развивать его дальше. Это совершенно необязательно — и спасибо!",
"The app version, Android version and phone model, so a problem is easier to find.": "Версия приложения, версия Android и модель телефона — чтобы проблему было проще найти.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Здесь перечислены пропатченные вами приложения вместе с журналом каждого запуска, чтобы их можно было установить снова, поделиться ими или сохранить в «Загрузки».",
"The archive file is rewritten without this file.": "Файл архива будет перезаписан без этого файла.",
"The archive file is rewritten without this folder and everything in it.": "Файл архива будет перезаписан без этой папки и всего её содержимого.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "Архив удаляется, только если все его файлы распакованы и ничего не пропущено.",
