"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "Настройки устройства system, secure и global. Неверное значение может нарушить работу устройства: меняйте по одной.",
"The download": "Загрузка",
"The download did not work.": "Загрузка не удалась.",
"The download failed:": "Загрузка не удалась:",
"The download is saved: Use this file": "Загрузка сохранена: Использовать этот файл",
"The edit could not start": "Не удалось начать изменение",
"The exclusions SD Maid SE ships with come back, the ones you removed too. Yours stay.": "Исключения, поставляемые с SD Maid SE, возвращаются, в том числе удалённые вами. Ваши остаются.",
"The exclusions could not be read.": "Не удалось прочитать исключения.",
"The extra button on every row of the Apps list. Choose what a tap on it does. Press and hold it on a row for a sheet with every action for that app.": "Дополнительная кнопка в каждой строке списка приложений. Выберите, что делает нажатие на неё. Долгое нажатие на строку открывает лист со всеми действиями для этого приложения.",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Дополнительные клавиши работают как в Termux: ESC очищает строку, TAB дополняет имя файла, CTRL-C останавливает выполняемое, стрелки перебирают прежние команды и перемещают курсор, HOME и END переходят в начало и конец строки, а | / - ~ вынесены сюда, потому что клавиатуры телефонов их скрывают.",
"The extraction could not start": "Не удалось начать распаковку",
"The file": "Файл",
"The file and its log are removed. The app on the phone is not touched.": "Файл и его журнал удаляются. Приложение на телефоне не затрагивается.",
"The file chooser needs the app build": "Для выбора файла нужна сборка приложения",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "Файл удаляется из памяти телефона, а не только из списка. Панель отмены остаётся на несколько секунд, и файл удаляется окончательно только после того, как она исчезнет.",
"The file was saved, but it is not an app file (unknown). Choose another download in the browser.": "Файл сохранён, но это не файл приложения (неизвестный). Выберите в браузере другую загрузку.",
"The fingerprint is shown in the app build": "Отпечаток отображается в приложении",
"The folder": "Папка",
"The folder and everything in it is removed from the device.": "Папка и всё, что в ней, будут удалены с устройства.",
"The font could not be loaded, so the system font is used.": "Шрифт не удалось загрузить, поэтому используется системный.",
"The font file is missing.": "Файл шрифта отсутствует.",
"The font of the text in this app. It does not change the font of the rest of your phone.": "Шрифт текста в этом приложении. Шрифт остального телефона не меняется.",
"The font search needs the app build": "Для поиска шрифтов нужна сборка приложения",
"The font the system uses": "Шрифт, который использует система",
"The full information could not be loaded: unknown error": "Не удалось загрузить полную информацию: неизвестная ошибка",
"The full path on the device.": "Полный путь на устройстве.",
"The full-screen terminal needs the app (not a plain browser)": "Полноэкранному терминалу нужно приложение (а не обычный браузер)",
"The gist returned no content.": "Gist не вернул содержимое.",
"The guide could not be loaded. Close this and try again.": "Не удалось загрузить руководство. Закройте это окно и повторите попытку.",
