"This phone has no Bluetooth.": "В этом телефоне нет Bluetooth.",
"This phone is not connected to its own ADB. Turn on ADB in this app's Working mode first (Working Mode button at the top), then try again.": "Этот телефон не подключён к собственному ADB. Сначала включите ADB в режиме работы этого приложения (кнопка «Режим работы» вверху), затем повторите попытку.",
"This phone is not connected to its own ADB: turn on ADB in Working mode first.": "Этот телефон не подключён к собственному ADB: сначала включите ADB в режиме работы.",
"This phone lists no overlays.": "На этом телефоне нет оверлеев.",
"This picture could not be loaded. Check the connection and open it again.": "Не удалось загрузить это изображение. Проверьте соединение и откройте его снова.",
"This picture could not be shown here. Try Open with…": "Не удалось показать это изображение. Попробуйте «Открыть с помощью…»",
