"This version is not one the patches list. Patching may fail. Get a supported version with Morphe Helper, or patch anyway.": "Этой версии нет среди версий патчей. Патчинг может не сработать. Получите поддерживаемую версию с помощью Morphe Helper или пропатчите всё равно.",
