"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Для поиска шрифтов в хранилище приложению нужен доступ ко всем файлам. Можно также выбрать файл шрифта вручную, и тогда доступ не нужен.",
"To search storage, this app needs": "Чтобы искать в хранилище, приложению нужно:",
"To search the files on this phone, this app needs All-files access.": "Чтобы искать файлы на этом телефоне, приложению нужен доступ ко всем файлам.",
