"When a Wi-Fi sign-in page is found (0 ignore, 1 ask, 2 avoid the network)": "Когда найдена страница входа в Wi-Fi (0 — игнорировать, 1 — спросить, 2 — избегать сети)",
"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "При удалении дубликатов SD Maid решает, какой файл оставить, проверяя каждый критерий по порядку. Первый критерий, дающий явного победителя, определяет результат. Перетаскивайте, чтобы изменить порядок, нажимайте, чтобы сменить режим.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "Когда выбранный источник не имеет версии или не работает, режимы «Эта версия», «Новейшая» и «Все версии» переходят к следующему источнику в порядке выше, пока один не сработает.",
