"Without it AppCleaner still deletes every cache it can reach with file access and, with a working mode, trims the caches of all apps at once.": "Без неё AppCleaner всё равно удаляет все кэши, до которых дотягивается через доступ к файлам, а в режиме работы очищает кэши всех приложений разом.",
