"Yes": "Да",
"You can grant or revoke it here.": "Здесь его можно предоставить или отозвать.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Вы изменили этот APK, поэтому его подпись больше недействительна, и Android не установит его как есть.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Вы объясняете одну скрытую настройку Android (запись базы данных Settings.Global, Settings.Secure или Settings.System, те, что читает и записывает «settings get/put») человеку, который не разработчик.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Вы объясняете одну скрытую настройку Android (запись базы данных Settings.Global, Settings.Secure или Settings.System, те, что читает и записывает «settings get/put») человеку, который не разработчик. Скажите кратко: что она контролирует, что означают её значения, что происходит при изменении и безопасно ли её менять. Прямо скажите, если не знаете эту настройку (многие принадлежат производителю телефона), вместо того чтобы гадать, а затем скажите, на что намекает её название. Короткие абзацы, без заголовков.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Вы объясняете одну запись logcat Android человеку, который не разработчик. Скажите простыми словами и кратко: что означает эта строка,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Вы объясняете одну запись logcat Android человеку, который не разработчик. Скажите простыми словами и кратко: что означает эта строка, наиболее вероятную причину, важно ли это (безвредный шум, реальная проблема или сбой) и, если важно, что попробовать. Используйте короткие абзацы, без заголовков. Если строка слишком загадочна, чтобы объяснить уверенно, так и скажите и укажите, что ещё помогло бы. Не выдумывайте подробностей.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Вы помогаете с ADB и синтаксисом команд оболочки в терминале Android. Отвечайте кратко и практично.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Вы помогаете с ADB и синтаксисом команд оболочки в терминале Android. Отвечайте кратко и практично. Если хотите предложить пользователю ровно одну команду для выполнения здесь, поместите её отдельно внутри",
"You're on a metered connection (mobile data / hotspot).": "Вы используете лимитное подключение (мобильный интернет / точка доступа).",
